from pathlib import Path

ROOT = Path(__file__).resolve().parent
BASE = 'context/35_full_programme_execution_20261112/'
ASOF = '2026-11-12'
PINS = json.loads((ROOT/'source_pins.json').read_text())

def write_json(name, obj):
    (ROOT/name).write_text(json.dumps(obj, ensure_ascii=False, indent=2, allow_nan=False)+'\n')

def write_csv(name, rows, fields=None):
    if fields is None:
        fields = list(dict.fromkeys(k for r in rows for k in r))
    with (ROOT/name).open('w', newline='') as out:
        w=csv.DictWriter(out,fieldnames=fields);w.writeheader();w.writerows(rows)

def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def extract(name):return json.loads((ROOT/'inputs'/name).read_text())
def source_bytes(owner,path):return subprocess.check_output(['git','show',PINS['pins'][owner]+':'+path])

# Только небольшие связанные с Омском строки и контрактные pins.
additional=[]
for owner,path in [
 ('P00R','context/34_full_programme_plan_20261112/variant_research_plan.json'),
 ('P00R','context/34_full_programme_plan_20261112/common_spec.json'),
 ('P03',BASE+'P03/aircraft_type_parameters.csv'),
 ('P03',BASE+'P03/operating_rules.json'),
 ('P06',BASE+'P06/engine/operations.py'),
 ('REASSESS','context/33_five_city_reassessment_20261112/cities/GOJ/routes.csv'),
 ('REASSESS','context/33_five_city_reassessment_20261112/cities/PEE/routes.csv'),
 ('REASSESS','context/33_five_city_reassessment_20261112/cities/UFA/routes.csv')]:
    raw=source_bytes(owner,path)
    rec={'owner':owner,'commit':PINS['pins'][owner],'path':path,'source_sha256':hashlib.sha256(raw).hexdigest()}
    if owner=='REASSESS':
        rows=[]
        for n,r in enumerate(csv.DictReader(io.StringIO(raw.decode())),2):
            if r.get('origin')=='OMS' or r.get('destination')=='OMS':
                rows.append({'source_row_number_header_is_1':n,'source_row_sha256':hashlib.sha256(json.dumps(r,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest(),'row':r})
        dest='inputs/REASSESS_'+path.split('/')[-2]+'_OMS.json';write_json(dest,rows);rec['local_extract']=dest
    elif path.endswith('variant_research_plan.json'):
        x=json.loads(raw);selected=[r for r in x['legacy_hypotheses'] if r['candidate_id'] in ('C04','C07')]
        write_json('inputs/PLAN_OMS_ancestry.json',selected);rec['local_extract']='inputs/PLAN_OMS_ancestry.json'
    additional.append(rec)
write_json('additional_source_pins.json',additional)

